from pathlib import Path
import json,statistics
r=Path(__file__).resolve().parents[1]/'reports';out=r/'transport_head_t2_20261026'
assert json.loads((out/'FINAL_CHECK.json').read_text())['passed']
paths={'transport':'transport_head_t2_20261026','old_response':'old_response_t2_20261026','feature_anchor':'feature_anchor_t2_20261026','frozen':'frozen_encoder_t2_20261026','subspace':'head_subspace_t2_20261026','adapting':'head_centered_loss_20261026'}
def extract(m):
 s=m['stages'][1];c=s['centered'];return {'raw':{'overall':100*s['all_seen'],'old':100*s['old_accuracy'],'new':100*s['new_accuracy'],'restricted':[100*v for v in s['restricted']]},'centered':{'overall':100*c['all_seen_accuracy'],'old':100*c['old_all_seen_accuracy'],'new':100*c['current_all_seen_accuracy'],'restricted':[100*v['restricted_accuracy'] for v in c['per_task']]}}
res={}
for arm,path in paths.items():
 seeds=[{'seed':seed,**extract(json.loads((r/path/f'seed{seed}/metrics.json').read_text()))} for seed in range(3)]
 res[arm]={'seeds':seeds,'mean':{mode:{k:statistics.mean(x[mode][k] for x in seeds) for k in ['overall','old','new']} for mode in ['raw','centered']},'sample_std':{mode:{k:statistics.stdev(x[mode][k] for x in seeds) for k in ['overall','old','new']} for mode in ['raw','centered']}}
a=res['transport'];b=res['old_response'];delta={mode:{k:a['mean'][mode][k]-b['mean'][mode][k] for k in ['overall','old','new']} for mode in ['raw','centered']}
paired={mode:{k:[x[mode][k]-y[mode][k] for x,y in zip(a['seeds'],b['seeds'])] for k in ['overall','old','new']} for mode in ['raw','centered']}
d=delta['centered'];checks={'mean_old_gain_at_least_half_pp':d['old']>=.5-1e-9,'mean_new_change_at_least_minus_half_pp':d['new']>=-.5-1e-9,'mean_overall_gain_at_least_quarter_pp':d['overall']>=.25-1e-9,'each_seed_old_change_nonnegative':all(v>=-1e-9 for v in paired['centered']['old'])}
qual=[json.loads((out/f'seed{s}/QUALIFICATION.json').read_text()) for s in range(3)]
qs_old=[json.loads((r/f'old_response_t2_20261026/seed{s}/QUALIFICATION.json').read_text()) for s in range(3)]
cost={'training_visits':sum(q['new_training_visits'] for q in qual),'teacher_forward_images':sum(q['new_teacher_forward_images'] for q in qual),'paired_statistic_encoder_forward_images':sum(q['new_statistics_visits'] for q in qual),'new_optimizer_steps':sum(q['new_optimizer_steps'] for q in qual),'paired_unique_current_images':sum(q['paired_samples'] for q in qual),'new_certificates':sum(q['new_certificates_passed'] for q in qual),'preflight_backward_images':sum(q['preflight_backward_images'] for q in qual),'preflight_teacher_forward_images':sum(q['preflight_extra_teacher_forward_images'] for q in qual),'task_evaluation_plus_reload_images':12000,'control_training_repeated':False,'logical_communication_bytes_total':sum(sum(q['new_communication_bytes'].values()) for q in qual),'old_response_same_protocol_logical_communication_bytes_total':sum(sum(q['new_communication_bytes'].values()) for q in qs_old)}
cost['extra_logical_communication_bytes_vs_old_response']=cost['logical_communication_bytes_total']-cost['old_response_same_protocol_logical_communication_bytes_total']
proxy={'raw_response_mse_improves_vs_raw_FedAvg_rounds':sum(a<b for q in qual for a,b in zip(q['raw_response_MSE_by_round'],q['raw_FedAvg_response_MSE_by_round'])),'rounds_total':15,'per_seed':[{'seed':s,'feature_squared_drift':q['paired_feature_squared_drift_mean_by_round'],'raw_response_mse':q['raw_response_MSE_by_round'],'raw_FedAvg_response_mse':q['raw_FedAvg_response_MSE_by_round']} for s,q in enumerate(qual)],'limits':'Raw MSE comparison is within the new paired representation against the raw-FedAvg counterfactual; minimized certificate is for alpha=.5 shrunk paired objective. Neither establishes superior classification or superiority to the old_response matching objective.'}
report={'scope':'All three T2 development seeds, fixed raw and centered rules; primary old_response control reused without training','arms':res,'delta_vs_old_response_pp':delta,'paired_delta_pp':paired,'paired_delta_sample_std_pp':{mode:{k:statistics.stdev(values) for k,values in metrics.items()} for mode,metrics in paired.items()},'gate':{'checks':checks,'passed':all(checks.values()),'all_integrity_passed':True},'cost':cost,'proxy_diagnostics':proxy}
(out/'FINAL_COMPARISON.json').write_text(json.dumps(report,indent=2)+'\n')
(out/'DECISION.json').write_text(json.dumps({'status':'ALL_THREE_QUALIFIED_T2_GATE_'+('PASSED' if all(checks.values()) else 'FAILED'),'gate':report['gate'],'next':'Close transport short-route study with all results retained. User separately authorized the mature current-only Head-RegMean vs standard LoRM six-run ten-task study, which is already running; its continuation is independent of this gate. No further transport/T3 or short-method successors.','no_coefficient_sweep_or_costly_retry':True,'ten_task_study_is_this_transport_method':False},indent=2)+'\n')
job=json.loads((out/'job.json').read_text())
lines=['paired local/global head response匹配 T2：三个seed完成，全部实现验收通过。','',f"固定centered均值：总体{a['mean']['centered']['overall']:.4f}%、旧{a['mean']['centered']['old']:.4f}%、新{a['mean']['centered']['new']:.4f}%。",f"相对旧响应保持对照：总体{d['overall']:+.4f}pp、旧{d['old']:+.4f}pp、新{d['new']:+.4f}pp；各seed旧变化{paired['centered']['old']}pp。",'预先冻结的T2 gate：'+str(report['gate']),'','逐seed（固定centered overall/old/new）：']
for s in a['seeds']:lines.append(f"seed{s['seed']}: {s['centered']['overall']:.2f}/{s['centered']['old']:.2f}/{s['centered']['new']:.2f}%")
lines += ['',f"raw变化vs同一对照：{delta['raw']}pp。两种推理规则、所有seed及背景对照完整保留。",f"paired响应raw MSE在{proxy['raw_response_mse_improves_vs_raw_FedAvg_rounds']}/15轮低于raw-FedAvg反事实，但实际证书针对alpha=.5收缩目标；它不证明分类改善，也不能把该结构差异宣称为旧/新类问题的已证实原因。",'','最终实际checkpoint：每seed50个新增clientround、125000训练访问/125000 teacher forward、50000 paired统计encoder forward、5个新部署证书、10个旧/新class、2次merge/history commit及24个B归零，首轮完整B/rawhead exact pairing、旧head/source/teacher与完整raw+centered重载验收通过。共享T1记录与task-start RRS不计入新增T2成本。',f"成本合计：{cost}",f"job exit[0,0,0]，ended{job['ended']}；新增目录{job['new_allocated_bytes']}bytes，旧lineage{job['lineage_allocated_bytes']}bytes，原clock不变。",'','用户已明确转向成熟current-only CE Head-RegMean与标准LoRM的六条完整十任务；该研究已独立启动，与本transport门槛独立。此短程路线只收尾归档，不做T3、不扫参数、不追加短程变体，不因本结果中断十任务队列。所有证据仍属共享测试集开发结果，无独立held-out确认。']
(out/'FINAL_RESULTS_ZH.txt').write_text('\n'.join(lines)+'\n')
print(json.dumps({'means':a['mean'],'delta':delta,'gate':report['gate'],'proxy_improved_rounds':proxy['raw_response_mse_improves_vs_raw_FedAvg_rounds'],'cost':cost},ensure_ascii=False,indent=2))
